"use client";

/**
 * Default skill-repositories + MCP-Market catalog (Skills PRD).
 *
 * A STATIC, always-available registry of:
 *   1. The default skill repositories the agent can pull additional SKILL.md
 *      skills from. ALL of them are ALSO BUNDLED AS LOCAL FILES under
 *      `public/skill-repos/<id>/` (generated by scripts/bundle_skill_repos.py
 *      — user request 2026-10-18: "add them as files, not repo links"), so
 *      browsing + installing works with zero GitHub round-trips:
 *        - "skill-collection": repos that contain SKILL.md folders. Indexed
 *          metadata-first (name + one-liner per skill); the full instructions
 *          load ONLY when a task actually needs that skill (manage_skill
 *          catalog → install_from_repository → read).
 *        - "npm-cli"-style repos that are CLI tools: they are installed and
 *          run INSIDE the E2B sandbox via `run_terminal` (never via
 *          manage_skill). api-anything and everything-ai are HYBRIDS — a
 *          bundled SKILL.md collection AND sandbox CLI usage.
 *   2. The MCP-Market catalog — curated MCPMarket servers with REAL
 *      connection configs bundled as local files under
 *      `public/mcp-market/index.json` (extracted from each server's
 *      marketplace page + GitHub README): remote HTTP endpoints are
 *      registered directly via manage_mcp create; stdio/npx/uvx servers run
 *      inside the E2B sandbox via an MCP client script.
 *
 * This registry is surfaced through `analyze_workspace` (the skill-repository
 * index the PRD requires) and the `manage_skill` "catalog" action. The static
 * entries below are the offline FALLBACK; the bundled manifests are the
 * source of truth at runtime (see repo-browser.ts).
 */

// ---------------------------------------------------------------------------
// Skill repositories.
// ---------------------------------------------------------------------------

export type RepositoryKind = "skill-collection" | "npm-cli";

/** Metadata-only entry for one skill inside a repository. */
export interface RepoSkillMeta {
  /** Skill name (kebab-case — the name it installs under). */
  name: string;
  /** One-line description (from the skill's front-matter / the PRD). */
  description: string;
  /** Repo-relative directory containing the SKILL.md ("" = repo root). */
  dir: string;
}

/** How to install + run an npm-cli repository inside the E2B sandbox. */
export interface SandboxUsage {
  /** Install commands (run inside the sandbox via run_terminal). */
  install: string;
  /** How to invoke once installed. */
  run: string;
  /** A concrete example invocation. */
  example?: string;
  /** Security / correctness requirement from the PRD. */
  caution?: string;
}

export interface SkillRepository {
  /** Stable id used by manage_skill (repository parameter). */
  id: string;
  /** Display name. */
  name: string;
  kind: RepositoryKind;
  owner: string;
  repo: string;
  /** Subdirectory holding the skills ("" = whole repo). */
  subpath: string;
  /** Fallback branch when the GitHub API default-branch lookup fails. */
  branch?: string;
  /** Public repository URL. */
  url: string;
  description: string;
  /** Static per-skill metadata index. [] → browse the bundled manifest / live. */
  skills: RepoSkillMeta[];
  /** Present for npm-cli / hybrid repositories. */
  sandboxUsage?: SandboxUsage;
  /**
   * True when the repository's skills are bundled as local files under
   * `public/skill-repos/<id>/` (manifest.json + skills/…). Bundled files are
   * fetched same-origin — no GitHub API, no jsDelivr, no rate limits.
   */
  bundled?: boolean;
}

