// ---------------------------------------------------------------------------
// Lookup + summary helpers.
// ---------------------------------------------------------------------------

export function getSkillRepository(id: string): SkillRepository | null {
  return SKILL_REPOSITORIES.find((r) => r.id === id) ?? null;
}

export function getMcpMarketServer(id: string): McpMarketServer | null {
  return MCP_MARKET_SERVERS.find((s) => s.id === id) ?? null;
}

/** Compact repo summary for `analyze_workspace` (metadata-only, no flooding). */
export interface SkillRepositorySummary {
  id: string;
  name: string;
  kind: RepositoryKind;
  description: string;
  url: string;
  skill_count: number;
  /** True when the skills are indexed statically; false → browse the bundle/live. */
  indexed: boolean;
  /** True when the repository is bundled as local files (offline installs). */
  bundled: boolean;
}

export function summarizeSkillRepositories(): SkillRepositorySummary[] {
  return SKILL_REPOSITORIES.map((r) => ({
    id: r.id,
    name: r.name,
    kind: r.kind,
    description: r.description,
    url: r.url,
    skill_count: r.skills.length,
    indexed: r.skills.length > 0,
    bundled: r.bundled === true,
  }));
}

/** MCP-Market summary for `analyze_workspace` (id + name + URL only). */
export function summarizeMcpMarket(): Array<Pick<McpMarketServer, "id" | "name" | "url">> {
  return MCP_MARKET_SERVERS.map((s) => ({ id: s.id, name: s.name, url: s.url }));
}

/** The catalog payload for `manage_skill` action "catalog" (metadata-first). */
export function buildSkillCatalogPayload() {
  return {
    repositories: SKILL_REPOSITORIES.map((r) => ({
      id: r.id,
      name: r.name,
      kind: r.kind,
      description: r.description,
      url: r.url || undefined,
      bundled: r.bundled === true,
      skill_count: r.skills.length,
      skills: r.skills.map((s) => ({ name: s.name, description: s.description })),
      ...(r.sandboxUsage
        ? {
            sandbox_install: r.sandboxUsage.install,
            sandbox_run: r.sandboxUsage.run,
            ...(r.sandboxUsage.example ? { example: r.sandboxUsage.example } : {}),
            ...(r.sandboxUsage.caution ? { caution: r.sandboxUsage.caution } : {}),
          }
        : {}),
    })),
    mcp_market: {
      note: "Run manage_mcp action 'market' — it returns the FULL bundled connection configs (remote URLs / stdio commands), no web_fetch needed.",
      servers: MCP_MARKET_SERVERS.map((s) => ({
        id: s.id,
        name: s.name,
        url: s.url,
        ...(s.hint ? { hint: s.hint } : {}),
      })),
    },
    usage:
      "Metadata-first: pick ONLY the skills relevant to the task, then manage_skill install_from_repository (all repositories are BUNDLED AS LOCAL FILES — installs are offline and instant), then 'read' the skill. Hybrid repos (api-anything, everything-ai) ALSO have sandbox_install commands for run_terminal. For MCP Market servers: manage_mcp action 'market' returns the bundled configs — remote HTTP servers register directly via manage_mcp create; stdio servers run inside the E2B sandbox via an MCP client script.",
  };
}
